250: 		FOREACH(struct mux_connection *conn, &dev->connections) {
251: 			if(dev->next_sport == conn->sport) {
252: 				dev->next_sport++;
253: 				ok = 0;
254: 				break;
255: 			}
256: 		} ENDFOREACH
