959: int usb_process(void)
960: {
961: 	int res;
962: 	struct timeval tv;
963: 	tv.tv_sec = tv.tv_usec = 0;
964: 	res = libusb_handle_events_timeout(NULL, &tv);
965: 	if(res < 0) {
966: 		usbmuxd_log(LL_ERROR, "libusb_handle_events_timeout failed: %s", libusb_error_name(res));
967: 		return res;
