973: 	if(dev_poll_remain_ms() <= 0) {
974: 		res = usb_discover();
975: 		if(res < 0) {
976: 			usbmuxd_log(LL_ERROR, "usb_discover failed: %s", libusb_error_name(res));
977: 			return res;
978: 		}
979: 	}
