    {
      "dimension": "native_api",
      "field": "type",
      "kind": "new_value",
      "value": "libusb",
      "rationale": "硬件/USB 访问通过 libusb API 完成，无法简单归入 win32/posix/syscall 等既有家族，故新增 libusb 作为 hardware 类型。"
    },
    {
      "dimension": "capability_profile",
      "field": "scenarios[].kind",
      "kind": "new_value",
      "value": "usb_device_access",
      "rationale": "推荐 kind 列表侧重 usb_serial/bluetooth/camera 等，而 usbmuxd 的核心场景是与 Apple iOS 设备进行 USB 协议级通信，更接近 usb_device_access。"
    },
    {
      "dimension": "harmony_adaptation",
      "field": "recommended_path",
      "kind": "new_value",
      "value": "ohos_native_service_rewrite",
      "rationale": "对于守护进程类应用，移植路径不是简单的重编或 Node-API 桥接，而是改写为 OHOS 系统服务/ability 并替换 Linux 激活与权限模型。"
    },
    {
      "dimension": "harmony_adaptation",
      "field": "blockers[].category",
      "kind": "new_value",
      "value": "linux_system_integration",
      "rationale": "udev/systemd 激活、/var 固定路径等 Linux 系统集成点无法直接映射到鸿蒙，需要独立分类。"
    },
    {
      "dimension": "harmony_adaptation",
      "field": "blockers[].category",
      "kind": "new_value",
      "value": "posix_daemon_model",
      "rationale": "fork/setsid/setuid/initgroups 等 Unix 守护进程原语在鸿蒙 PC 支持状态未核实，需单独标记。"
    }
  ],
  "warnings": []
}
